k Your Shoot ↗</a></section></main><?php require __DIR__.'/includes/site-footer.php'; ?><script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js" defer></script><script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js" defer></script><script src="assets/reference/app.js" defer></script><?php require_once __DIR__.'/includes/ui.php'; acp_ui(); ?><script>document.addEventListener("DOMContentLoaded",()=>{const a=document.getElementById("acpAccountLinks"),n=document.getElementById("acpMainNav");if(a&&n&&!document.getElementById("acpAccountSlot"))n.appendChild(a);});</script><script src="assets/reference/password-toggle.js" defer></script></body></html>